UPDATE email_templates
SET description = 'Email kích hoạt tài khoản Staff và thông tin đăng nhập tạm thời',
    body_html = '<!DOCTYPE html><html lang="vi"><body style="font-family:Arial,sans-serif;line-height:1.6;color:#333"><h2>Xin chào, {{fullName}}!</h2><p>Admin đã tạo tài khoản Staff TripStay cho bạn.</p><p>Email đăng nhập: <strong>{{email}}</strong><br>Mật khẩu tạm: <strong>{{temporaryPassword}}</strong></p><p>Nhấn vào liên kết bên dưới để xác thực email và kích hoạt tài khoản:</p><p><a href="{{invitationLink}}">Kích hoạt tài khoản Staff</a></p><p>Sau khi kích hoạt, bạn đăng nhập tại <strong>/manager/login</strong> bằng email và mật khẩu tạm ở trên.</p><p>Liên kết chỉ dùng một lần và sẽ hết hạn sau 24 giờ.</p><p>Trân trọng,<br>Đội ngũ TripStay</p></body></html>',
    body_text = 'Xin chào, {{fullName}}!\n\nAdmin đã tạo tài khoản Staff TripStay cho bạn.\n\nEmail đăng nhập: {{email}}\nMật khẩu tạm: {{temporaryPassword}}\n\nMở liên kết sau để xác thực email và kích hoạt tài khoản:\n{{invitationLink}}\n\nSau khi kích hoạt, đăng nhập tại /manager/login bằng email và mật khẩu tạm.\nLiên kết chỉ dùng một lần và sẽ hết hạn sau 24 giờ.\n\nTrân trọng,\nĐội ngũ TripStay'
WHERE code = 'STAFF_INVITATION';
